-- PostgreSQL 15+; synthetic planning metadata only.
CREATE SCHEMA IF NOT EXISTS urban_demo;
CREATE TABLE IF NOT EXISTS urban_demo.applications(application_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_ref TEXT NOT NULL UNIQUE,applicant_token TEXT NOT NULL,locality_code TEXT NOT NULL,development_type TEXT NOT NULL CHECK(development_type IN('residential','commercial','industrial','public_facility','renovation','other')),submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','under_review','approved','declined','withdrawn')),decision_note TEXT);
CREATE TABLE IF NOT EXISTS urban_demo.permits(permit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,permit_ref TEXT NOT NULL UNIQUE,application_id BIGINT NOT NULL UNIQUE REFERENCES urban_demo.applications(application_id) ON DELETE RESTRICT,issued_on DATE,expires_on DATE,status TEXT NOT NULL CHECK(status IN('active','suspended','expired','closed')),permit_type TEXT NOT NULL,document_ref TEXT NOT NULL,CHECK(expires_on IS NULL OR issued_on IS NULL OR expires_on>=issued_on));
CREATE TABLE IF NOT EXISTS urban_demo.inspections(inspection_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,inspection_ref TEXT NOT NULL UNIQUE,application_id BIGINT NOT NULL REFERENCES urban_demo.applications(application_id) ON DELETE RESTRICT,inspected_at TIMESTAMPTZ NOT NULL,inspection_type TEXT NOT NULL CHECK(inspection_type IN('site_progress','document_review','follow_up','other')),outcome TEXT NOT NULL CHECK(outcome IN('pending','acceptable','follow_up_required','referred')),inspector_ref TEXT NOT NULL,summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS urban_demo.actions(action_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,action_ref TEXT NOT NULL UNIQUE,inspection_id BIGINT NOT NULL REFERENCES urban_demo.inspections(inspection_id) ON DELETE RESTRICT,summary TEXT NOT NULL,owner_ref TEXT NOT NULL,due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','closed','cancelled')),closed_at TIMESTAMPTZ,CHECK(status<>'closed' OR closed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS urban_demo.action_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,action_id BIGINT NOT NULL REFERENCES urban_demo.actions(action_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','closed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_urban_application_status ON urban_demo.applications(status,submitted_at DESC);
CREATE INDEX IF NOT EXISTS ix_urban_permit_expiry ON urban_demo.permits(status,expires_on);
CREATE INDEX IF NOT EXISTS ix_urban_actions_due ON urban_demo.actions(status,due_date) WHERE status NOT IN('closed','cancelled');